export type MessageId = keyof typeof messages;
export type MessagePrimitive = string | number;
export type MessageValues = Readonly<Record<string, MessagePrimitive>>;

export type MessageParameters = {
        "ui.motherboardResizableBarSupportState": { status: string };
        "ui.ruleMatchScope": { rule: number };
        "ui.ruleActionSize": { rule: number };
        "ui.completionRecordedAt": { time: string };
        "ui.driverRawAndBootStepsRecorded": { raw: string };
        "ui.profileInspectorVersionInstalled": { version: string };
        "ui.fallbackRuleFact": { deviceId: string; selector: number | string };
        "ui.patchConfigurationState": { status: string };
        "ui.configurationSaved": { bytes: number; time: string };
        "ui.bootRecordedAfterConfiguration": { bootTime: string; savedTime: string };
        "ui.profileGpusObserved": { hash: string };
        "ui.editorProcessLaunched": { processId: number };
        "ui.legacyProfileCreated": { ruleCount: number };
        "ui.hardwareCheckDifferences": { differenceCount: number };
        "ui.analysisFailedRetryImage": { detail: string };
        "ui.deploymentOperationFailed": { detail: string };
        "ui.configureOperationFailed": { detail: string };
        "ui.saveReceiptSummary": { bytes: number; state: string };
};
export type ParameterizedMessageId = keyof MessageParameters;
export type StaticMessageId = Exclude<MessageId, ParameterizedMessageId>;

export type MessageDescriptor = {
        [Id in MessageId]: Id extends keyof MessageParameters
                ? { id: Id; values: MessageParameters[Id] }
                : { id: Id; values?: never };
}[MessageId];

export function message<Id extends keyof MessageParameters>(
        id: Id,
        values: MessageParameters[Id],
): Extract<MessageDescriptor, { id: Id }>;
export function message<Id extends StaticMessageId>(
        id: Id,
): Extract<MessageDescriptor, { id: Id }>;
export function message(
        id: MessageId,
        values?: MessageValues,
): MessageDescriptor {
        return (values ? { id, values } : { id }) as MessageDescriptor;
}
